class Solution {
public:
    int leastBricks(vector<vector<int>>& wall) {
        unordered_map<int, int> edgeCounts;
        int maxEdges = 0;
        for (const auto& row : wall) {
            int curr = 0;
            for (size_t i = 0; i + 1 < row.size(); ++i) {
                curr += row[i];
                edgeCounts[curr]++;
                maxEdges = max(maxEdges, edgeCounts[curr]);
            }
        }
        return wall.size() - maxEdges;
    }
};

class Solution {
    public int leastBricks(List<List<Integer>> wall) {
        Map<Integer, Integer> edgeCounts = new HashMap<>();
        int maxEdges = 0;
        for (List<Integer> row : wall) {
            int curr = 0;
            for (int i = 0; i < row.size() - 1; i++) {
                curr += row.get(i);
                int cnt = edgeCounts.getOrDefault(curr, 0) + 1;
                edgeCounts.put(curr, cnt);
                maxEdges = Math.max(maxEdges, cnt);
            }
        }
        return wall.size() - maxEdges;
    }
}

